{
  "ledger": {
    "p77:e595": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "단편적 텍스트('Worked for 1m >')로 연구 내용이 포함되지 않았으며, 승인된 사실(P0077F0001, P0077F0002)에 대응하지 않음."
    },
    "p77:e596": {
      "state": "represented",
      "fact_ids": ["P0077F0001"],
      "note": "'측정이 잘못된 것이 아니라 초소형 데이터(1KB)의 역설이 정직하게 나타난 것'이라는 해석이 P0077F0001에 보존됨."
    },
    "p77:e597": {
      "state": "represented",
      "fact_ids": ["P0077F0002"],
      "note": "앞부분('Pinned Memory가 무조건 빠르다, 데이터가 충분히 클 때라는 전제 조건')은 P0077F0002에 보존됨. 후반부('1KB에서 No-Pin이 더 빠른 하드웨어적 비밀을 설명하겠다')는 승인된 사실에 미포함."
    },
    "p77:e598": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "비유 heading('옆집 가는데 KTX 타는 격')으로, 승인된 사실에 대응하는 연구 내용 없음."
    },
    "p77:e599": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "목록 헤더('No-Pin: 일반 메모리 → CPU가 직접 복사')만 존재하며 승인된 사실에 대응하는 내용 없음."
    },
    "p77:e600": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "1,028 Byte의 CPU L1 캐시 복사 시간 20~30나노초(0.00003ms) 등 구체적 수치가 포함되었으나 승인된 사실에 보존되지 않음."
    },
    "p77:e601": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "목록 헤더('Pinned Memory: GPU DMA 엔진 호출')만 존재하며 승인된 사실에 대응하는 내용 없음."
    },
    "p77:e602": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "PCIe DMA 엔진 가동, 명령 패킷/트랜잭션 셋업 오버헤드 1~2마이크로초(0.0015ms) 등 구체적 주장이 포함되었으나 승인된 사실에 보존되지 않음."
    },
    "p77:e603": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "92만 번 루프, DMA 셋업 오버헤드 누적, infer 단계 13초 차이(132초 vs 119초) 등 구체적 수치가 포함되었으나 승인된 사실에 보존되지 않음."
    },
    "p77:enh:e0": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e595와 동일 내용('Worked for 1m >'). 표준 파싱(p77:e595)이 우선하며, enhanced_page_image는 중복 표현."
    },
    "p77:enh:e1": {
      "state": "duplicate",
      "fact_ids": ["P0077F0001"],
      "note": "p77:e596과 동일 내용. P0077F0001에 이미 보존된 내용의 중복 표현."
    },
    "p77:enh:e2": {
      "state": "duplicate",
      "fact_ids": ["P0077F0002"],
      "note": "p77:e597의 앞부분과 동일 내용. P0077F0002에 이미 보존된 내용의 중복 표현."
    },
    "p77:enh:e3": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "p77:e597의 후반부('1KB에서 No-Pin이 더 빠른 하드웨어적 비밀을 설명하겠다')를 별도 추출한 요소. 승인된 사실에 미포함."
    },
    "p77:enh:e4": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e598과 동일 내용(비유 heading). 표준 파싱이 우선."
    },
    "p77:enh:e5": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e599와 동일 내용(No-Pin 목록 헤더). 표준 파싱이 우선."
    },
    "p77:enh:e6": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e600과 동일 내용(20~30나노초 복사 시간 등). 표준 파싱이 우선."
    },
    "p77:enh:e7": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e601과 동일 내용(Pinned Memory 목록 헤더). 표준 파싱이 우선."
    },
    "p77:enh:e8": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e602와 동일 내용(PCIe DMA 엔진, 1~2마이크로초 오버헤드 등). 표준 파싱이 우선."
    },
    "p77:enh:e9": {
      "state": "duplicate",
      "fact_ids": [],
      "note": "p77:e603과 동일 내용(92만 번 루프, 13초 차이 등)이나 OCR 오류($\\mu\\text{tu}\\text{text{s}$) 포함. 표준 파싱이 우선."
    }
  }
}
